<script setup lang="ts">
import { ArrowLeft, Search, Save, Upload } from 'lucide-vue-next'
import { attributeLabels, genres, occasions, restaurantSchema, type Restaurant } from '../../../../shared/domain'
const app=useApp();const route=useRoute();const id=ref(String(route.params.id));const isNew=computed(()=>id.value==='new');const message=ref('');const busy=ref(false);const loaded=ref(false);const query=ref('');const places=ref<any[]>([]);const rights=ref('');const alt=ref('');const credit=ref('');const file=ref<File|null>(null)
const form=reactive<Restaurant>({id:'00000000-0000-4000-8000-000000000000',slug:'',citySlug:'osaka',name:'',area:'梅田',description:'',recommendationText:'',priceMin:1000,priceMax:2000,editorialScore:3,coverImageUrl:'/images/ramen.webp',genres:[],attributes:{},partySizes:[1,2],occasions:[],status:'draft',placeId:'',images:[],demo:false})
async function load(){if(!app.isAdmin.value||loaded.value)return;if(isNew.value){loaded.value=true;return}try{Object.assign(form,await app.api<Restaurant>(`/api/admin/restaurants/${id.value}`));loaded.value=true}catch{message.value='店舗を取得できませんでした。'}}watch(()=>app.isAdmin.value,()=>load(),{immediate:true})
async function save(publish=false){busy.value=true;message.value='';try{const checked=restaurantSchema.safeParse(form);if(!checked.success||form.priceMax<form.priceMin){message.value='入力を確認してください。店名・URL・予算・画像URLは必須です。';return}const result=await app.api<Restaurant>(isNew.value?'/api/admin/restaurants':`/api/admin/restaurants/${id.value}`,{method:isNew.value?'POST':'PATCH',body:{...checked.data,status:form.status==='published'?'draft':form.status}});id.value=result.id;Object.assign(form,result);if(publish){Object.assign(form,await app.api(`/api/admin/restaurants/${id.value}/publish`,{method:'POST'}))}message.value=publish?'公開しました。':'保存しました。公開する場合はプレビューを確認して「公開する」を押してください。';if(String(route.params.id)==='new')await navigateTo(`/admin/restaurants/${id.value}`,{replace:true})}catch(e:any){message.value=e.data?.statusMessage||'保存できませんでした。'}finally{busy.value=false}}
async function search(){busy.value=true;message.value='';try{const result=await app.api<{places:any[]}>('/api/admin/places/search',{method:'POST',body:{query:query.value}});places.value=result.places||[];if(!places.value.length)message.value='候補が見つかりませんでした。'}catch(e:any){message.value=e.data?.statusMessage||'検索できませんでした。'}finally{busy.value=false}}
async function upload(){if(!file.value||isNew.value)return;busy.value=true;message.value='';try{const body=new FormData();body.append('file',file.value);body.append('rights',rights.value);body.append('alt',alt.value);body.append('credit',credit.value);const r=await app.api<Restaurant>(`/api/admin/restaurants/${id.value}/images`,{method:'POST',body});form.images=r.images;message.value='画像を追加しました。カバー画像を選んで保存してください。'}catch(e:any){message.value=e.data?.statusMessage||'アップロードできませんでした。'}finally{busy.value=false}}
function toggle<T>(list:T[],v:T){const i=list.indexOf(v);if(i<0)list.push(v);else list.splice(i,1)}useHead({meta:[{name:'robots',content:'noindex'}]})
</script>
<template><section class="page narrow"><NuxtLink to="/admin" class="text-link"><ArrowLeft :size="16"/>店舗一覧へ</NuxtLink><h1>{{isNew?'店舗を追加':'店舗を編集'}}</h1><ClientOnly><div v-if="!app.isAdmin.value" class="empty-state"><h2>管理者権限が必要です</h2><NuxtLink to="/account" class="button primary">ログイン</NuxtLink></div><template v-else><form class="panel admin-form" @submit.prevent="save()"><h2>基本情報</h2><label class="field">店名<input v-model="form.name" required maxlength="100"/></label><label class="field">URL識別子（半角英数字とハイフン）<input v-model="form.slug" pattern="[a-z0-9-]+" required/></label><label class="field">エリア<input v-model="form.area" required/></label><label class="field">紹介文<textarea v-model="form.description" maxlength="2000" rows="4"/></label><label class="field">推薦コメント<textarea v-model="form.recommendationText" maxlength="300"/></label><div class="two-columns"><label class="field">最低予算<input v-model.number="form.priceMin" type="number" min="0" required/></label><label class="field">最高予算<input v-model.number="form.priceMax" type="number" :min="form.priceMin" required/></label></div><label class="field">基本おすすめ度（0〜5）<input v-model.number="form.editorialScore" type="number" min="0" max="5" step="0.1" required/></label><fieldset><legend>ジャンル</legend><div class="chips"><button v-for="g in genres" :key="g.key" type="button" :class="{selected:form.genres.includes(g.key)}" :aria-pressed="form.genres.includes(g.key)" @click="toggle(form.genres,g.key)">{{g.label}}</button></div></fieldset><fieldset><legend>人数への適合</legend><div class="chips"><button v-for="p in [1,2,4,5]" :key="p" type="button" :class="{selected:form.partySizes.includes(p)}" :aria-pressed="form.partySizes.includes(p)" @click="toggle(form.partySizes,p)">{{p===4?'3〜4人':p===5?'5人以上':`${p}人`}}</button></div></fieldset><fieldset><legend>利用目的</legend><div class="chips"><button v-for="o in occasions" :key="o.key" type="button" :class="{selected:form.occasions.includes(o.key)}" :aria-pressed="form.occasions.includes(o.key)" @click="toggle(form.occasions,o.key)">{{o.label}}</button></div></fieldset><fieldset><legend>属性の適合度（0〜1）</legend><div class="attribute-inputs"><label v-for="(label,key) in attributeLabels" :key="key">{{label}}<input :value="form.attributes[key]||0" type="number" min="0" max="1" step="0.1" @input="e=>{const n=Number((e.target as HTMLInputElement).value);if(n)form.attributes[key]=n;else delete form.attributes[key]}"/></label></div></fieldset><label class="field">状態<select v-model="form.status"><option value="draft">非公開</option><option value="published">公開（公開ボタンで反映）</option><option value="closed">閉店・一時休止</option></select></label><p v-if="message" class="notice" role="status">{{message}}</p><button type="submit" class="button primary" :disabled="busy"><Save :size="17"/>保存する</button></form>
 <section class="panel admin-form"><h2>Google Placesとの紐付け</h2><form class="inline-form" @submit.prevent="search"><input v-model="query" aria-label="Google Placesで店名を検索" placeholder="店名で検索" minlength="2" required/><button class="button secondary" :disabled="busy"><Search :size="17"/>検索</button></form><p class="muted">検索結果の情報提供：Google Maps</p><button v-for="p in places" :key="p.id" class="place-result" @click="form.placeId=p.id;form.name ||= p.displayName?.text;places=[]"><strong>{{p.displayName?.text}}</strong><span>{{p.formattedAddress}}</span></button><label class="field">Place ID<input v-model="form.placeId" maxlength="300"/></label><p class="muted">紐付け後に「保存する」を押してください。</p></section>
 <section class="panel admin-form"><h2>料理画像</h2><p v-if="isNew" class="notice">先に店舗を保存してから画像を追加してください。</p><form v-else @submit.prevent="upload"><label class="field">画像（JPEG / PNG / WebP、5MB以下）<input type="file" accept="image/jpeg,image/png,image/webp" required @change="e=>file=(e.target as HTMLInputElement).files?.[0]||null"/></label><label class="field">代替テキスト<input v-model="alt" required/></label><label class="field">使用権の確認記録<input v-model="rights" required placeholder="撮影者・許諾日・使用条件など"/></label><label class="field">クレジット<input v-model="credit"/></label><button class="button secondary" :disabled="busy"><Upload :size="17"/>画像を追加</button></form><div class="image-picker"><button v-for="i in form.images" :key="i.url" :class="{selected:form.coverImageUrl===i.url}" :aria-pressed="form.coverImageUrl===i.url" @click="form.coverImageUrl=i.url"><img :src="i.url" :alt="i.alt"/><span>{{form.coverImageUrl===i.url?'✓ カバー画像':'カバーに選ぶ'}}</span></button></div></section>
 <section class="panel admin-form"><h2>公開前プレビュー</h2><img class="preview-image" :src="form.coverImageUrl" :alt="form.name||'プレビュー'"/><h3>{{form.name}}</h3><p>{{form.recommendationText}}</p><p>{{form.description}}</p><button class="button primary" :disabled="busy||isNew" @click="save(true)">保存して公開する</button><p class="muted">使用権を確認した画像をカバーに選ぶと公開できます。</p><p v-if="message" class="notice" role="status">{{message}}</p></section></template></ClientOnly></section></template>
